// Saga coordinator
public class OrderSaga
{
    private readonly IOrderService _orderService;
    private readonly IPaymentService _paymentService;
    private readonly IInventoryService _inventoryService;

    public async Task ExecuteAsync(Order order)
    {
        try
        {
            // Step 1: Create order
            await _orderService.CreateOrderAsync(order);

            // Step 2: Process payment
            await _paymentService.ProcessPaymentAsync(order.Payment);

            // Step 3: Reserve inventory
            await _inventoryService.ReserveInventoryAsync(order.Items);

            // Saga complete
            await _orderService.MarkAsCompletedAsync(order.Id);
        }
        catch (Exception ex)
        {
            // Compensating transactions
            await CompensateAsync(order);
            throw;
        }
    }

    private async Task CompensateAsync(Order order)
    {
        try
        {
            await _inventoryService.ReleaseInventoryAsync(order.Items);
            await _paymentService.RefundPaymentAsync(order.Payment);
            await _orderService.MarkAsFailedAsync(order.Id);
        }
        catch (Exception ex)
        {
            // Log and handle compensation failure
            // May require manual intervention
        }
    }
}
